interface.definition:
a!localVariables(
  local!showQueuedCount: false,
  local!jobTypeCounts: a!refreshVariable(
    value: #"SYSTEM_SYSRULES_queryRecordType_v1"(
      recordType: #"urn:appian:record-type:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a",
      fields: {
        #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/isActive",
        #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning",
        #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount",
        #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount",
        if(
          local!showQueuedCount,
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/queuedCount",
          {}
        )
      },
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
        startIndex: 1,
        batchSize: #"_a-0000ec53-364e-8000-9bbd-011c48011c48_9160"
      )
    ).data,
    refreshInterval: #"_a-0000ec54-b070-8000-9bc1-011c48011c48_10966"
  ),
  local!runningCount: sum(
    local!jobTypeCounts[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount"]
  ),
  local!queuedCount: sum(
    local!jobTypeCounts[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/queuedCount"]
  ),
  local!failedCount: sum(
    local!jobTypeCounts[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount"]
  ),
  local!capacityUsed: #"_a-0000e4d6-77d9-8000-8592-01ef9001ef90_107641"(
    runningCount: local!runningCount,
    failedCount: local!failedCount,
    maxRunning: sum(
      if(
        local!jobTypeCounts[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/isActive"],
        local!jobTypeCounts[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning"],
        0
      )
    )
  ) / 100,
  local!capacityUsedText: text(local!capacityUsed, "0%"),
  local!jobTypeExecutionTimeRaw: #"SYSTEM_SYSRULES_executeStoredProcedureForQuery"(
    dataSource: #"_a-0000e3d0-178b-8000-8592-01ef9001ef90_105371",
    procedureName: "TM_GET_AVG_JOB_TYPE_EXEC_TIME"
  ),
  local!jobTypeExecutionTime: if(
    #"_a-0000e80a-7cbc-8000-051f-01ef9001ef90_18055",
    local!jobTypeExecutionTimeRaw.parameters.result,
    local!jobTypeExecutionTimeRaw.results
  ),
  #"SYSTEM_SYSRULES_headerContentLayout"(
    header: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_stampField"(
                          labelPosition: "COLLAPSED",
                          icon: "sliders",
                          contentColor: "STANDARD"
                        ),
                        width: "MINIMIZE"
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "Consola de operación",
                              size: "LARGE",
                              color: "#FFFFFF",
                              style: "STRONG"
                            )
                          }
                        )
                      )
                    },
                    alignVertical: "MIDDLE"
                  )
                },
                width: "WIDE"
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_boxLayout"(
                    label: "Fallos",
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        label: "",
                        labelPosition: "ABOVE",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: { local!failedCount },
                            size: "LARGE",
                            color: if(
                              local!failedCount > 0,
                              "NEGATIVE",
                              "POSITIVE"
                            ),
                            style: { "STRONG" }
                          )
                        },
                        align: "CENTER"
                      )
                    },
                    marginBelow: "STANDARD",
                    style: "INFO"
                  )
                },
                width: ""
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_boxLayout"(
                    label: "Capacidad usada",
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        label: "",
                        labelPosition: "ABOVE",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: { local!capacityUsedText },
                            size: "LARGE",
                            color: #"_a-0000e3b4-3090-8000-8592-01ef9001ef90_104730"(local!capacityUsedText),
                            style: { "STRONG" }
                          )
                        },
                        align: "CENTER"
                      )
                    },
                    iscollapsible: false,
                    marginBelow: "STANDARD",
                    style: "INFO"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_boxLayout"(
                    label: "En ejecución",
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        label: "",
                        labelPosition: "ABOVE",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: { local!runningCount },
                            size: "LARGE",
                            style: { "STRONG" }
                          )
                        },
                        align: "CENTER"
                      )
                    },
                    marginBelow: "STANDARD",
                    style: "INFO"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_boxLayout"(
                    label: "Encolados",
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        label: "",
                        labelPosition: "ABOVE",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: { "Calcular total" },
                            showWhen: not(local!showQueuedCount),
                            link: #"SYSTEM_SYSRULES_dynamicLink"(
                              saveInto: a!save(
                                target: local!showQueuedCount,
                                value: true
                              )
                            )
                          ),
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: { local!queuedCount },
                            showWhen: local!showQueuedCount,
                            size: "LARGE",
                            style: { "STRONG" }
                          )
                        },
                        align: "CENTER"
                      )
                    },
                    marginBelow: "STANDARD",
                    style: "INFO",
                    padding: if(local!showQueuedCount, null, "STANDARD")
                  )
                }
              )
            },
            alignVertical: "MIDDLE",
            spacing: "STANDARD"
          )
        },
        marginBelow: "STANDARD",
        style: "#1d2d44",
        showBorder: false,
        padding: "LESS"
      )
    },
    contents: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            items: {
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                  labelPosition: "COLLAPSED",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "exclamation-triangle",
                      size: "MEDIUM",
                      color: "#ffc13e"
                    )
                  }
                ),
                width: "MINIMIZE"
              ),
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                  labelPosition: "COLLAPSED",
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(text: { "Warning:" }, style: "STRONG"),
                    " ",
                    "Transaction Manager is not running!"
                  }
                )
              ),
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                  buttons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                    label: "Enable",
                    saveInto: #"SYSTEM_SYSRULES_startProcess"(
                      processModel: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107172",
                      processParameters: { enable: true }
                    ),
                    size: "SMALL"
                  ),
                  marginBelow: "NONE"
                ),
                showWhen: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106893"(),
                width: "MINIMIZE"
              )
            },
            alignVertical: "MIDDLE"
          )
        },
        showWhen: not(#"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014"),
        accessibilityText: "Warning message",
        marginBelow: "STANDARD",
        style: "WARN"
      ),
      #"_a-0000e7da-c788-8000-d625-01ef9001ef90_28981"(
        title: "Métricas",
        contents: {
          /*Charts*/
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106912"(jobTypeId: null)
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_sectionLayout_v1"(
                    label: "Tiempo medio de ejecución",
                    contents: {
                      #"SYSTEM_SYSRULES_textField"(
                        label: " ",
                        labelPosition: "ABOVE",
                        instructions: "El tiempo promedio entre una transacción que se solicita para comenzar a ejecutarse hasta que se complete.",
                        readOnly: true
                      ),
                      #"SYSTEM_SYSRULES_columnChartField"(
                        labelPosition: "ABOVE",
                        categories: local!jobTypeExecutionTime.name,
                        series: {
                          #"SYSTEM_SYSRULES_chartSeries"(
                            label: "Tipos de trabajo",
                            data: local!jobTypeExecutionTime.execTime
                          )
                        },
                        height: "SHORT",
                        yAxisTitle: "Segundos",
                        showLegend: true,
                        showTooltips: true,
                        stacking: "NONE"
                      )
                    },
                    labelSize: "EXTRA_SMALL"
                  )
                },
                showWhen: and(
                  local!jobTypeExecutionTimeRaw.success,
                  a!isNotNullOrEmpty(local!jobTypeExecutionTime)
                )
              )
            }
          )
        }
      ),
      #"SYSTEM_SYSRULES_cardLayout"(style: "STANDARD", showBorder: false),
      /* Job Type Status Grid */
      #"_a-0000e7da-c788-8000-d625-01ef9001ef90_28981"(
        title: "Estado del tipo de trabajo",
        contents: { #"_a-0000e7da-c788-8000-d625-01ef9001ef90_29153"() }
      ),
      #"SYSTEM_SYSRULES_cardLayout"(style: "STANDARD", showBorder: false),
      /* Transaction Manager Settings*/
      #"_a-0000e7da-c788-8000-d625-01ef9001ef90_28981"(
        title: "Preferencias",
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            instructions: if(
              #"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014",
              null,
              "Espere 5 minutos para que las transacciones comiencen a procesarse"
            ),
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: "El gestor de transacciones está: ",
                size: "MEDIUM",
                style: "STRONG"
              ),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: if(
                  #"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014",
                  "En ejecucion",
                  "Apagado"
                ),
                size: "MEDIUM",
                color: if(#"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014", "POSITIVE", "NEGATIVE"),
                style: "STRONG"
              )
            }
          ),
          #"SYSTEM_SYSRULES_cardLayout"(showBorder: false),
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_cardLayout"(
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: if(
                              #"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014",
                              "DESACTIVAR GESTOR DE TRANSACCIONES",
                              "HABILITAR GESTOR DE TRANSACCIONES"
                            ),
                            color: "#888888",
                            style: "STRONG"
                          )
                        }
                      )
                    },
                    link: #"SYSTEM_SYSRULES_startProcessLink"(
                      processModel: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107172",
                      processParameters: { enable: not(#"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014") }
                    ),
                    padding: "LESS"
                  )
                },
                width: "NARROW_PLUS"
              ),
              #"SYSTEM_SYSRULES_columnLayout"()
            },
            showWhen: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106893"()
          )
        }
      )
    },
    backgroundColor: "TRANSPARENT"
  )
)
